$(function() {
  if ($('main.about').length > 0) {
    return $('.ui.accordion').accordion({
      onOpen: function() {
        return $('html, body').animate({
          'scrollTop': $('.active.title').offset().top - $('header').height()
        }, 300);
      }
    });
  }
});

$(function() {
  if ($('main.contact').length > 0) {
    return $('.submit-button').on('click', function() {
      var $form, formData, instance;
      $form = $(this).closest('form');
      formData = $form.serialize();
      instance = $form.parsley();
      if (instance.isValid()) {
        return $.ajax({
          type: 'POST',
          data: formData + "&action=mailchimp_register",
          url: ajaxurl,
          success: function(data) {
            data = JSON.parse(data);
            $.fancybox.close();
            if (data.success) {
              $('#success-message').fadeIn();
              return $('#error-message').fadeOut();
            } else {
              $('#success-message').fadeOut();
              return $('#error-message').fadeIn();
            }
          }
        });
      } else {
        instance.validate();
        return $('#error-message').fadeIn().delay(3000).fadeOut();
      }
    });
  }
});

$(function() {
  if ($('main.home').length > 0) {
    console.log('home');
    $('.posts-slider').slick({
      slidesToShow: 3,
      adaptiveHeight: true,
      arrows: false,
      responsive: [
        {
          breakpoint: 768,
          settings: {
            adaptiveHeight: false,
            arrows: false,
            centerMode: false,
            slidesToShow: 1,
            dots: true
          }
        }
      ]
    });
    window.code = null;
    window.promo_id = null;
    $(document).on('click', '.cloud', function() {
      var height, likelihood_number, posx, posy, type, typeName, width, win;
      height = $(this).height();
      width = $(this).width();
      $(this).remove();
      type = Math.floor(Math.random() * 3);
      typeName = '';
      likelihood_number = 0;
      switch (type) {
        case 0:
          typeName = 'noodles';
          likelihood_number = 0.5;
          break;
        case 1:
          typeName = 'appetizer';
          likelihood_number = 2;
          break;
        default:
          typeName = 'drink';
          likelihood_number = 6;
      }
      win = chance.bool({
        likelihood: likelihood_number
      });
      console.log('You clicked the hey', typeName, win);
      if (win) {
        $.ajax({
          type: 'POST',
          data: "&type=" + typeName + "&action=get_promo",
          url: ajaxurl,
          success: function(data) {
            data = JSON.parse(data);
            $.fancybox.close();
            if (data.success) {
              $('#promoform #promo_type').text(typeName);
              $.fancybox.open($('#promoform'), {
                touch: false
              });
              window.code = data.code;
              return window.promo_id = data.promo_id;
            } else {
              return console.log('ran out');
            }
          }
        });
      }
      //              $.fancybox.open $('#tryagain'), touch: false
      posx = (Math.random() * ($('#cloud-wrapper').width() - width)).toFixed();
      posy = (Math.random() * ($('#cloud-wrapper').height() - height)).toFixed();
      return $('<div class="cloud"><img src="../wp-content/themes/Madhouse/images/HEYNOODLES_Horizontal_Black.svg" alt=""></div>').css({
        'position': 'absolute',
        'left': posx + 'px',
        'top': posy + 'px',
        'display': 'none'
      }).appendTo('#cloud-wrapper').fadeIn('fast', function() {
        return console.log('generated');
      });
    });
    $(document).on('click', '#promoform .submit', function() {
      var $form, formData, instace;
      $form = $('#promoform form');
      formData = $form.serialize();
      instace = $form.parsley();
      if (instace.isValid()) {
        return $.ajax({
          type: 'POST',
          data: formData + "&code=" + window.code + "&promo_id=" + window.promo_id + "&action=claim_promo",
          url: ajaxurl,
          success: function(data) {
            data = JSON.parse(data);
            $.fancybox.close();
            if (data.success) {
              $('#successclaimed #promo_code').text(window.code);
              return $.fancybox.open($('#successclaimed'), {
                touch: false
              });
            } else {
              return $.fancybox.open($('#tryagain'), {
                touch: false
              });
            }
          }
        });
      } else {
        return instace.validate();
      }
    });
    $(document).on('click', '.fancybox-is-open .close', function() {
      return $.fancybox.close();
    });
    if ($(window).width() < 768) {
      return $('#values .table').slick({
        dots: true
      });
    }
  }
});

$(function() {
  var input, place_latlng, searchBox;
  if ($('main.locations').length > 0) {
    $('.accordion').accordion();
    console.log('locations');
    if ('geolocation' in navigator) {
      // check if geolocation is supported/enabled on current browser
      navigator.geolocation.getCurrentPosition((function(position) {
        var detectedLatlng, distance_array, indexOfMinValue;
        // for when getting location is a success
        detectedLatlng = new google.maps.LatLng(position.coords.latitude, position.coords.longitude);
        distance_array = [];
        $('.location').each(function(index) {
          var $location, distance, location_latlng;
          $location = $(this);
          location_latlng = new google.maps.LatLng($location.data('lat'), $location.data('lng'));
          console.log(location_latlng);
          distance = google.maps.geometry.spherical.computeDistanceBetween(detectedLatlng, location_latlng);
          return distance_array.push(distance);
        });
        //      indexOfMinValue = distance_array.indexOf(Math.min(distance_array))
        indexOfMinValue = distance_array.indexOf(Math.min.apply(Math, distance_array));
        console.log('indexOfMinValue', indexOfMinValue);
        $('.location').removeClass('active');
        $(".location:eq( " + indexOfMinValue + " )").addClass('active');
        return $('html, body').animate({
          scrollTop: $(".location:eq( " + indexOfMinValue + " )").offset().top - $('header').height()
        }, 1000);
      }), function(error_message) {
        // for when getting location results in an error
        console.error('An error has occured while retrieving location', error_message);
      });
    } else {
      console.log('geolocation is not enabled on this browser');
    }
    input = document.getElementById('address-bar');
    searchBox = new google.maps.places.SearchBox(input);
    console.log(searchBox);
    place_latlng = null;
    google.maps.event.addListener(searchBox, 'places_changed', function() {
      place_latlng = searchBox.getPlaces()[0].geometry.location;
      //      place_latlng = {
      //        lat: place_latlng.lat(),
      //        lng: place_latlng.lng()
      //      }
    });
    return $('#find-location').on('click', function() {
      var distance_array, indexOfMinValue;
      distance_array = [];
      $('.location').each(function(index) {
        var $location, distance, location_latlng;
        $location = $(this);
        //        location_latlng = {lat: $location.data('lat'), lng: $location.data('lng')}
        location_latlng = new google.maps.LatLng($location.data('lat'), $location.data('lng'));
        console.log(location_latlng);
        distance = google.maps.geometry.spherical.computeDistanceBetween(place_latlng, location_latlng);
        return distance_array.push(distance);
      });
      //      indexOfMinValue = distance_array.indexOf(Math.min(distance_array))
      indexOfMinValue = distance_array.indexOf(Math.min.apply(Math, distance_array));
      console.log('indexOfMinValue', indexOfMinValue);
      $('.location').removeClass('active');
      $(".location:eq( " + indexOfMinValue + " )").addClass('active');
      return $('html, body').animate({
        scrollTop: $(".location:eq( " + indexOfMinValue + " )").offset().top - $('header').height()
      }, 1000);
    });
  }
});

$(function() {
  if ($('main.menu').length > 0) {
    console.log('menu');
    return $('.ui.accordion').accordion({
      onOpen: function() {
        return $('html, body').animate({
          'scrollTop': $('.active.title').offset().top - $('header').height()
        }, 300);
      }
    });
  }
});

$(function() {
  var ctx, i, img, pixelate, play, randIndex, stTL;
  if ($('main.home').length > 0) {
    $('html').addClass('stop-scrolling');
    ctx = canvas.getContext('2d');
    img = new Image;
    play = false;
    window.animated = false;
    pixelate = function(v) {
      var h, ratio, size, w;
      // if in play mode use that value, else use slider value
      size = (play ? v : blocks.value) * 0.001;
      ratio = img.height / img.width;
      //    canvas.width = canvas.height/ratio
      w = canvas.width * size;
      h = canvas.height * size;
      console.log(size);
      ratio = img.height / img.width;
      //    ratio  = Math.min(hRatio, vRatio)
      //    ctx.drawImage(img, 0,0, img.width, img.height, 0,0,img.width*ratio, img.height*ratio)
      // draw original image to the scaled size
      ctx.imageSmoothingEnabled = false;
      ctx.drawImage(img, 0, 0, w, h);
      // then draw that scaled image thumb back to fill canvas
      // As smoothing is off the result will be pixelated
      return ctx.drawImage(canvas, 0, 0, w, h, 0, 0, canvas.height / ratio, canvas.height);
    };
    i = void 0;
    i = 0;
    setTimeout((function() {
      setInterval((function() {
        //        if i <= 5
        //          if i < 3
        //            blocks.value = 30*i
        //          else if i < 5
        //            blocks.value = (i-2) * 200
        //          else if i == 5
        //            blocks.value = 1000
        //          i++
        //          pixelate()

        //          return
        if (i <= 4) {
          blocks.value = (i + 1) * 200;
          i++;
          return pixelate();
        } else {
          $('#page-loader').delay(300).fadeOut();
          $('html').removeClass('stop-scrolling');
          return clearInterval(this);
        }
      }), 300);
    }), 200);
    //    while i < 5
    //      blocks.value = i*10
    //      i++

    // This runs the demo animation to give an impression of
    // performance.
    window.toggleAnim = function() {
      var anim, dx, v;
      // limit blocksize as we don't want to animate tiny blocks
      v = Math.min(25, parseInt(blocks.value, 10));
      dx = 0;
      /// "speed"
      // toggle play flag set by button "Animate"
      // animation loop
      anim = function() {
        // increase or decrease value
        v += dx;
        // if at min or max reverse delta
        if (v <= 1 || v > 25) {
          dx = -dx;
        }
        // pixelate image with current value
        pixelate(v);
        // loop
        if (play) {
          requestAnimationFrame(anim);
        }
      };
      play = !play;
      // and update button's text
      //    animate.value = if play then 'Stop' else 'Animate'
      //    # if in play mode start loop
      if (play === true) {
        anim();
      }
    };
    ctx.mozImageSmoothingEnabled = false;
    ctx.webkitImageSmoothingEnabled = false;
    ctx.imageSmoothingEnabled = false;
    // wait until image is actually available
    img.onload = pixelate;
    // some image, we are not struck with CORS restrictions as we
    // do not use pixel buffer to pixelate, so any image will do
    randIndex = Math.floor((Math.random() * 5) + 1);
    img.src = '../wp-content/themes/Madhouse/images/loader/HN_Loading_Image' + randIndex + '.jpg';
    // event listeneners for slider and button
    blocks.addEventListener('change', pixelate, false);
    //  animate.addEventListener 'click', toggleAnim, false
    // poly-fill for requestAnmationFrame with fallback for older
    // browsers which do not support rAF.
    window.requestAnimationFrame = (function() {
      return window.requestAnimationFrame || window.webkitRequestAnimationFrame || window.mozRequestAnimationFrame || function(callback) {
        window.setTimeout(callback, 1000 / 60);
      };
    })();
  }
  // ---
  // generated by js2coffee 2.2.0
  $('body').flowtype({
    minimum: 320,
    maximum: 2560,
    minFont: 13,
    maxFont: 20,
    fontRatio: 100
  });
  stTL = new TimelineMax();
  $('.img-fill').imgLiquid();
  //  img = document.querySelector('img')

  //  if img.complete
  //    $('#page-loader').delay(1000).fadeOut()
  //  else
  //    img.addEventListener 'load', loaded
  //    img.addEventListener 'error', ->
  //      $('#page-loader').delay(1000).fadeOut()
  //      return
  $(document).scroll(function() {
    if ($(document).scrollTop() >= 100) {
      return $('header').addClass('bg');
    } else {
      return $('header').removeClass('bg');
    }
  });
  return $('.hamburger').on('click', function() {
    $(this).toggleClass('is-active');
    $('body').toggleClass('lockScroll');
    $('html').toggleClass('stop-scrolling');
    return $('#main-nav').toggleClass('active');
  });
});
